import crypto from 'node:crypto';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { UAParser } from 'ua-parser-js';
import DeviceDetector from 'device-detector-js';
import { DEVICE_COOKIE, deviceCookieOptions } from './cookies.js';
import { placeForAddress, placeForCoordinates, countryName, isPrivateAddress } from './geo.js';

// The name catalogue is read once, at start-up, as plain JSON so nothing depends on an
// experimental loader flag. It is generated by scripts/build-device-names.js.
const CATALOGUE_FILE = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'data', 'device-names.json');
const deviceNames = JSON.parse(readFileSync(CATALOGUE_FILE, 'utf8'));

const UUID = /^[0-9a-f-]{36}$/i;
const FINGERPRINT = /^[0-9a-f]{16,64}$/;
const detector = new DeviceDetector();

// The client hashes a few stable browser signals into a short hex string. Anything
// that does not look exactly like one is ignored, so a caller cannot push arbitrary
// text into the database through this header.
export function deviceFingerprint(req) {
  const raw = String(req.get('x-device-fingerprint') || '')
    .trim()
    .toLowerCase();
  return FINGERPRINT.test(raw) ? raw : null;
}

// One slot per browser. The fingerprint is the better signal because clearing the
// device cookie cannot move you into a free slot, but the cookie is used whenever
// the client does not send one, so older clients still work.
export const deviceKey = (fingerprint, deviceId) => fingerprint || `cookie:${deviceId}`;

export function ensureDeviceId(req, res) {
  let id = req.cookies?.[DEVICE_COOKIE];
  if (!id || !UUID.test(id)) {
    id = crypto.randomUUID();
    res.cookie(DEVICE_COOKIE, id, deviceCookieOptions);
  }
  return id;
}

// ---------------------------------------------------------------------------
// Which address is this, and where is it?
//
// The site is served by Vercel, which forwards /api to this service. Vercel replaces
// x-real-ip and x-forwarded-for with the browser's own address, so those are the only
// honest source on that path: reading Cloudflare's own header instead reported the
// Vercel proxy, which sits in another country entirely. A caller cannot forge either
// header through Vercel, because Vercel overwrites both before forwarding.
// ---------------------------------------------------------------------------

const cleanIp = (value) => String(value || '').trim().replace(/^::ffff:/, '');
const usableIp = (ip) => Boolean(ip) && ip !== '::1' && !ip.startsWith('127.') && !isPrivateAddress(ip);

export function resolveClient(req) {
  if (req.get('x-vercel-id')) {
    const forwarded = String(req.get('x-forwarded-for') || '').split(',')[0];
    const ip = cleanIp(req.get('x-real-ip') || forwarded);
    if (usableIp(ip)) return { ip, via: 'vercel' };
  }

  const edge = cleanIp(req.get('cf-connecting-ip'));
  if (usableIp(edge)) return { ip: edge, via: 'cloudflare' };

  return { ip: cleanIp(req.ip || req.socket?.remoteAddress), via: 'direct' };
}

// Vercel also works out the place from the true address, so on that path no lookup is
// needed at all. It is only read when Vercel says it handled the request.
function edgePlace(req) {
  if (!req.get('x-vercel-id')) return '';

  let city = String(req.get('x-vercel-ip-city') || '');
  try {
    city = decodeURIComponent(city);
  } catch {
    // leave the raw value; it is only a label
  }

  const country = countryName(req.get('x-vercel-ip-country'));
  return [city.trim(), country].filter(Boolean).join(', ');
}

// ---------------------------------------------------------------------------
// What the device calls itself.
//
// Modern Chrome freezes the version numbers inside the user agent string on purpose: it
// reports "Windows 10" on Windows 11, and "Android 10" on every Android since. The browser
// will still answer honestly when asked directly through the User-Agent Client Hints API.
// The client asks once, sends the answer in a small header, and this reads it back.
//
// The model code it reports is translated through the device catalogue that ships in
// data/device-names.json, which is generated from Google Play's supported-device list.
// A name that is not in that list is never invented: the code is shown as it arrived.
//
// None of it is evidence of anything. It is a label in an alert and on a list, and it is
// never used to decide who anybody is or what they may do.
// ---------------------------------------------------------------------------

const MAX_HINTS = 1200;
const WINDOWS_11_FROM = 13; // the API version Windows 11 starts at
const ANDROID_API = { 8: 26, 9: 28, 10: 29, 11: 30, 12: 31, 13: 33, 14: 34, 15: 35, 16: 36 };

// Model codes carry the maker's name in their first letters, and the phone in the hand is
// the only thing that knows the rest.
const MODEL_BRANDS = [
  [/^(SM|GT|SCH|SGH|SHV|SPH)-/i, 'Samsung'],
  [/^Pixel/i, 'Google'],
  [/^TECNO/i, 'Tecno'],
  [/^Infinix/i, 'Infinix'],
  [/^itel/i, 'itel'],
  [/^(HUAWEI|ANE|MAR|JNY|ELE|VOG|LIO|CLT|LYA)/i, 'Huawei'],
  [/^moto/i, 'Motorola'],
  [/^Nokia/i, 'Nokia'],
  [/^CPH|^OPPO/i, 'OPPO'],
  [/^RMX/i, 'realme'],
  [/^V\d{4}/i, 'vivo'],
  [/^(ONEPLUS|OnePlus)/i, 'OnePlus'],
  [/^XT\d/i, 'Motorola'],
  [/^iPhone|^iPad/i, 'Apple'],
];

const text = (value, max) => (typeof value === 'string' && value.trim() && value.length <= max ? value.trim() : undefined);

function readHints(req) {
  const raw = String(req.get('x-device-info') || '');
  if (!raw || raw.length > MAX_HINTS) return null;

  try {
    const parsed = JSON.parse(Buffer.from(raw, 'base64url').toString('utf8'));
    return {
      platform: text(parsed.platform, 40),
      platformVersion: text(parsed.platformVersion, 20),
      model: text(parsed.model, 60),
      architecture: text(parsed.architecture, 20),
      bitness: text(parsed.bitness, 8),
      browser: text(parsed.browser, 40),
      browserVersion: text(parsed.browserVersion, 20),
      mobile: typeof parsed.mobile === 'boolean' ? parsed.mobile : undefined,
    };
  } catch {
    return null;
  }
}

// Coordinates the person explicitly allowed on the sign-in screen, rounded by the client.
// They are read, turned into a place, and never stored.
const COORDS = /^(-?\d{1,3}(?:\.\d{1,6})?),\s*(-?\d{1,3}(?:\.\d{1,6})?)$/;

function readCoords(req) {
  const match = COORDS.exec(String(req.get('x-device-location') || '').trim());
  if (!match) return null;
  const lat = Number(match[1]);
  const lon = Number(match[2]);
  if (!Number.isFinite(lat) || !Number.isFinite(lon) || Math.abs(lat) > 90 || Math.abs(lon) > 180) return null;
  return { lat, lon };
}

const bitness = (hints) => {
  if (!hints?.architecture) return '';
  const arm = hints.architecture === 'arm';
  if (arm && hints.bitness === '64') return 'ARM64';
  if (!arm && hints.bitness === '64') return 'x64';
  if (arm && hints.bitness === '32') return 'ARM';
  return hints.bitness === '32' ? 'x86' : hints.architecture;
};

function systemLabel(hints, ua) {
  const name = hints?.platform || ua.os.name || '';
  const version = hints?.platformVersion || ua.os.version || '';

  if (name === 'Windows') {
    const major = Number.parseInt(version, 10);
    const edition = Number.isFinite(major) && major >= WINDOWS_11_FROM ? 'Windows 11' : 'Windows 10';
    const bits = bitness(hints);
    return bits ? `${edition} ${bits}` : edition;
  }

  if (name === 'Android') {
    const major = Number.parseInt(version, 10);
    if (!Number.isFinite(major)) return 'Android';
    const api = ANDROID_API[major];
    return api ? `Android ${major} (${api})` : `Android ${major}`;
  }

  if (name === 'macOS' || name === 'Mac OS X') {
    const bits = bitness(hints);
    return [`macOS ${version}`.trim(), bits].filter(Boolean).join(' ');
  }

  if (name === 'Chrome OS') return `Chrome OS ${version}`.trim();
  if (name === 'iOS') return `iOS ${version}`.trim();

  return [name, version].filter(Boolean).join(' ') || 'Unknown system';
}

const BROWSER_NAMES = {
  'Google Chrome': 'Chrome',
  'Microsoft Edge': 'Edge',
  Chromium: 'Chromium',
};

function browserLabel(ua, hints) {
  const hintName = hints?.browser ? BROWSER_NAMES[hints.browser] ?? hints.browser : '';
  const name = hintName || ua.browser.name;
  const version = hints?.browserVersion || ua.browser.version || '';
  const major = String(version).split('.')[0];
  return [name, major].filter(Boolean).join(' ') || 'Unknown browser';
}

function typeLabel(hints, ua) {
  if (hints?.mobile === true) return 'mobile';
  if (hints?.mobile === false) return ua.device?.type || 'desktop';
  return ua.device?.type || 'desktop';
}

const brandFor = (model) => MODEL_BRANDS.find(([pattern]) => pattern.test(model))?.[1];

// "SM-M135F/DS" is the same phone with two SIM slots; the catalogue lists it without
// the suffix.
function catalogueName(model) {
  const key = String(model || '').trim().toUpperCase();
  if (!key) return '';
  return deviceNames[key] || deviceNames[key.replace(/\/DS$/, '')] || '';
}

function resolveDevice(hints, ua) {
  // What the browser itself reported. On a phone this is the maker's model code, which the
  // catalogue turns into a name when it knows it.
  const reported = hints?.model || ua.device?.model;
  if (reported) {
    const known = catalogueName(reported);
    if (known) return { name: known, source: 'catalogue' };

    const vendor = brandFor(reported) || ua.device?.vendor;
    const prefix = vendor && !reported.toLowerCase().startsWith(vendor.toLowerCase()) ? `${vendor} ` : '';
    return { name: `${prefix}${reported}`.trim(), source: 'reported' };
  }

  const parsed = detector.parse(ua.ua || '');
  if (parsed?.device?.brand && parsed?.device?.model) {
    return { name: `${parsed.device.brand} ${parsed.device.model}`.trim(), source: 'reported' };
  }

  return { name: '', source: 'unavailable' };
}

export async function describeRequest(req) {
  const agent = req.get('user-agent') || '';
  const ua = new UAParser(agent).getResult();
  const hints = readHints(req);
  const { ip } = resolveClient(req);

  // A place the person allowed is better than any estimate; the edge's own answer is next;
  // the address lookup is the last resort, and every one of them is labelled as an estimate
  // except the first.
  const coords = readCoords(req);
  const shared = coords ? await placeForCoordinates(coords.lat, coords.lon) : '';
  const fromEdge = shared ? '' : edgePlace(req);
  const location = shared || fromEdge || (await placeForAddress(ip));
  const locationSource = shared ? 'device' : fromEdge ? 'edge' : 'network';

  const device = resolveDevice(hints, ua);

  return {
    ip,
    userAgent: agent.slice(0, 300),
    browser: browserLabel(ua, hints),
    os: systemLabel(hints, ua),
    deviceType: typeLabel(hints, ua),
    deviceName: device.name,
    deviceModelSource: device.source,
    location,
    locationSource,
  };
}
